package com.smartcanteen.ui;
import com.smartcanteen.model.*;import com.smartcanteen.service.CanteenService;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.math.BigDecimal;
public class AdminDashboard extends JFrame {
 private final CanteenService service;private final DefaultTableModel foods=new DefaultTableModel(new Object[]{"ID","Name","Description","Price","Available"},0){public boolean isCellEditable(int r,int c){return false;}};
 private final DefaultTableModel orders=new DefaultTableModel(new Object[]{"Order ID","Student","Total","Status","Date"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable foodTable=new JTable(foods),orderTable=new JTable(orders);private final JLabel sales=new JLabel("Today's completed sales: ₹0.00");
 public AdminDashboard(User user,CanteenService service){super("Smart Canteen - Admin");this.service=service;setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(900,600);setLocationRelativeTo(null);JTabbedPane tabs=new JTabbedPane();tabs.addTab("Menu management",menuPanel());tabs.addTab("Orders",ordersPanel());JPanel report=new JPanel(new BorderLayout());report.add(sales,BorderLayout.NORTH);JButton refresh=UIUtil.button("Refresh sales");refresh.addActionListener(e->refreshSales());report.add(refresh,BorderLayout.CENTER);tabs.addTab("Sales",report);add(tabs,BorderLayout.CENTER);JButton logout=UIUtil.button("Logout");logout.addActionListener(e->{dispose();new LoginFrame().setVisible(true);});add(logout,BorderLayout.SOUTH);refreshFoods();refreshOrders();refreshSales();}
 private JPanel menuPanel(){JPanel p=UIUtil.panel();p.add(new JScrollPane(foodTable),BorderLayout.CENTER);JPanel buttons=new JPanel();JButton add=UIUtil.button("Add food"),edit=UIUtil.button("Edit selected"),toggle=UIUtil.button("Toggle availability"),refresh=UIUtil.button("Refresh");buttons.add(add);buttons.add(edit);buttons.add(toggle);buttons.add(refresh);p.add(buttons,BorderLayout.SOUTH);add.addActionListener(e->foodDialog(null));edit.addActionListener(e->{int r=foodTable.getSelectedRow();if(r<0){UIUtil.info(this,"Select a food item.");return;}foodDialog(r);});toggle.addActionListener(e->{int r=foodTable.getSelectedRow();if(r<0)return;try{int id=(int)foods.getValueAt(r,0);boolean current=(boolean)foods.getValueAt(r,4);service.setAvailability(id,!current);refreshFoods();}catch(Exception ex){UIUtil.error(this,ex);}});refresh.addActionListener(e->refreshFoods());return p;}
 private void foodDialog(Integer row){JTextField name=new JTextField(row==null?"":String.valueOf(foods.getValueAt(row,1)));JTextField desc=new JTextField(row==null?"":String.valueOf(foods.getValueAt(row,2)));JTextField price=new JTextField(row==null?"":String.valueOf(foods.getValueAt(row,3)).replace("₹",""));JCheckBox available=new JCheckBox("Available",row==null||Boolean.TRUE.equals(foods.getValueAt(row,4)));JPanel p=new JPanel(new GridLayout(0,2,6,6));p.add(new JLabel("Food name"));p.add(name);p.add(new JLabel("Description"));p.add(desc);p.add(new JLabel("Price"));p.add(price);p.add(new JLabel("Availability"));p.add(available);if(JOptionPane.showConfirmDialog(this,p,row==null?"Add food":"Edit food",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){try{Integer id=row==null?null:(int)foods.getValueAt(row,0);service.saveFood(id,name.getText(),desc.getText(),price.getText(),available.isSelected());refreshFoods();}catch(Exception ex){UIUtil.error(this,ex);}}}
 private JPanel ordersPanel(){JPanel p=UIUtil.panel();p.add(new JScrollPane(orderTable),BorderLayout.CENTER);JPanel actions=new JPanel();JComboBox<String> status=new JComboBox<>(new String[]{"PENDING","PREPARING","READY","COMPLETED","CANCELLED"});JButton update=UIUtil.button("Update selected status"),refresh=UIUtil.button("Refresh orders");actions.add(status);actions.add(update);actions.add(refresh);p.add(actions,BorderLayout.SOUTH);update.addActionListener(e->{int r=orderTable.getSelectedRow();if(r<0){UIUtil.info(this,"Select an order.");return;}try{service.updateOrderStatus((int)orders.getValueAt(r,0),(String)status.getSelectedItem());refreshOrders();refreshSales();}catch(Exception ex){UIUtil.error(this,ex);}});refresh.addActionListener(e->refreshOrders());return p;}
 private void refreshFoods(){try{foods.setRowCount(0);for(FoodItem f:service.allFoods())foods.addRow(new Object[]{f.getFoodId(),f.getFoodName(),f.getDescription(),"₹"+f.getPrice(),f.isAvailable()});}catch(Exception e){UIUtil.error(this,e);}}
 private void refreshOrders(){try{orders.setRowCount(0);for(OrderSummary o:service.allOrders())orders.addRow(new Object[]{o.getOrderId(),o.getStudentName(),"₹"+o.getTotal(),o.getStatus(),o.getDate()});}catch(Exception e){UIUtil.error(this,e);}}
 private void refreshSales(){try{sales.setText("Today's completed sales: ₹"+service.todaySales());}catch(Exception e){UIUtil.error(this,e);}}
}
